CREATE EXTENSION IF NOT EXISTS pgcrypto;
DO $$ BEGIN CREATE TYPE account_type AS ENUM('MEMBER','ADMIN','BROKER'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE user_role AS ENUM('MEMBER','OWNER','OWNER_ASSISTANT'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE user_status AS ENUM('ACTIVE','PENDING','SUSPENDED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE request_status AS ENUM('PENDING','NEEDS_CORRECTION','APPROVED','REJECTED_FINAL'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),telegram_id text UNIQUE NOT NULL,telegram_username varchar(255),telegram_name varchar(255),account_type account_type NOT NULL DEFAULT 'MEMBER',role user_role NOT NULL DEFAULT 'MEMBER',status user_status NOT NULL DEFAULT 'ACTIVE',is_verified boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),request_number bigint GENERATED ALWAYS AS IDENTITY UNIQUE,user_id uuid NOT NULL REFERENCES users(id),applicant_type account_type NOT NULL,full_name varchar(150) NOT NULL,father_phone varchar(30) NOT NULL,national_id varchar(100) NOT NULL,latitude numeric(10,7) NOT NULL,longitude numeric(10,7) NOT NULL,location_accuracy numeric(10,2),status request_status NOT NULL DEFAULT 'PENDING',reviewed_by uuid REFERENCES users(id),review_note text,submitted_at timestamptz NOT NULL DEFAULT now(),reviewed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS one_active_request_per_user ON requests(user_id) WHERE status IN('PENDING','NEEDS_CORRECTION');
CREATE TABLE IF NOT EXISTS request_files(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),request_id uuid NOT NULL REFERENCES requests(id) ON DELETE CASCADE,file_type varchar(50) NOT NULL,original_name text NOT NULL,stored_name text NOT NULL,mime_type varchar(150) NOT NULL,file_size bigint NOT NULL,storage_path text NOT NULL,sha256_hash char(64) NOT NULL,telegram_file_id text,telegram_chat_id text,status varchar(30) NOT NULL DEFAULT 'ACTIVE',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS complaints(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),complainant_id uuid NOT NULL REFERENCES users(id),target_user_id uuid NOT NULL REFERENCES users(id),target_type account_type NOT NULL,body text NOT NULL,status varchar(40) NOT NULL DEFAULT 'NEW',owner_note text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS complaint_files(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),complaint_id uuid NOT NULL REFERENCES complaints(id) ON DELETE CASCADE,original_name text NOT NULL,stored_name text NOT NULL,mime_type varchar(150) NOT NULL,file_size bigint NOT NULL,storage_path text NOT NULL,sha256_hash char(64) NOT NULL,telegram_file_id text,telegram_chat_id text,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE complaints ADD COLUMN IF NOT EXISTS assigned_to uuid REFERENCES users(id);
ALTER TABLE complaints ADD COLUMN IF NOT EXISTS due_at timestamptz;
ALTER TABLE complaints ADD COLUMN IF NOT EXISTS attachment_warning text;
CREATE TABLE IF NOT EXISTS complaint_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),complaint_id uuid NOT NULL REFERENCES complaints(id) ON DELETE CASCADE,sender_id uuid NOT NULL REFERENCES users(id),body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS complaint_messages_complaint_created_idx ON complaint_messages(complaint_id, created_at);
ALTER TABLE request_files ADD COLUMN IF NOT EXISTS telegram_file_id text;
ALTER TABLE request_files ADD COLUMN IF NOT EXISTS telegram_chat_id text;
ALTER TABLE complaint_files ADD COLUMN IF NOT EXISTS telegram_file_id text;
ALTER TABLE complaint_files ADD COLUMN IF NOT EXISTS telegram_chat_id text;
CREATE TABLE IF NOT EXISTS broker_finance(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),broker_id uuid UNIQUE NOT NULL REFERENCES users(id),monthly_finance numeric(14,2) NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS broker_lifts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),broker_id uuid NOT NULL REFERENCES users(id),total_amount numeric(14,2) NOT NULL,payment_method varchar(20) NOT NULL CHECK(payment_method IN('CASH','INSTALLMENTS')),paid_amount numeric(14,2) NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS broker_payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),broker_id uuid NOT NULL REFERENCES users(id),lift_id uuid REFERENCES broker_lifts(id),payment_type varchar(30) NOT NULL,amount numeric(14,2) NOT NULL CHECK(amount>0),payment_date timestamptz NOT NULL DEFAULT now(),recorded_by uuid REFERENCES users(id),note text);
CREATE TABLE IF NOT EXISTS announcements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),category varchar(30) NOT NULL,title varchar(250) NOT NULL,body text NOT NULL,audience varchar(30) NOT NULL DEFAULT 'ALL',important boolean NOT NULL DEFAULT false,published boolean NOT NULL DEFAULT false,created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,title varchar(250) NOT NULL,body text NOT NULL,is_read boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS assistant_permissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),assistant_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,permission varchar(80) NOT NULL,UNIQUE(assistant_id,permission));
CREATE TABLE IF NOT EXISTS audit_logs(id bigserial PRIMARY KEY,actor_user_id uuid REFERENCES users(id),action varchar(100) NOT NULL,target_type varchar(100),target_id text,details jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,user_agent text,ip_address inet,created_at timestamptz NOT NULL DEFAULT now(),last_seen_at timestamptz NOT NULL DEFAULT now(),revoked_at timestamptz);
CREATE TABLE IF NOT EXISTS system_settings(key varchar(100) PRIMARY KEY,value jsonb NOT NULL,updated_by uuid REFERENCES users(id),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS backup_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),started_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,status varchar(30) NOT NULL,file_size bigint,sha256_hash char(64),telegram_message_id text,telegram_file_id text,encryption_algorithm varchar(40),trigger varchar(30) NOT NULL DEFAULT 'MANUAL',error_message text);
ALTER TABLE backup_logs ADD COLUMN IF NOT EXISTS telegram_file_id text;
ALTER TABLE backup_logs ADD COLUMN IF NOT EXISTS encryption_algorithm varchar(40);
ALTER TABLE backup_logs ADD COLUMN IF NOT EXISTS trigger varchar(30) NOT NULL DEFAULT 'MANUAL';
